import json, sys
data = json.load(sys.stdin)
json.dump(data, open('after-cpm-packages.json','w'), indent=2)

# Load baseline
baseline = json.load(open('baseline-packages.json'))

# Build lookup: (project, tfm, pkg) -> (req, res)
def build_map(d):
    m = {}
    for proj in d.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                m[(name, tfm, pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return m

before = build_map(baseline)
after = build_map(data)

all_keys = sorted(set(before.keys()) | set(after.keys()))

changes = []
unchanged = []
for k in all_keys:
    proj, tfm, pkg = k
    b = before.get(k)
    a = after.get(k)
    if b and a:
        if b[1] != a[1]:
            changes.append((proj, tfm, pkg, b[1], a[1], 'Aligned to highest version'))
        else:
            unchanged.append((proj, tfm, pkg, a[1]))
    elif b and not a:
        changes.append((proj, tfm, pkg, b[1], '-', 'Removed'))
    elif a and not b:
        changes.append((proj, tfm, pkg, '-', a[1], 'Added'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]:<15} {c[1]:<10} {c[2]:<50} {c[3]:<12} -> {c[4]:<12} {c[5]}')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]:<15} {u[1]:<10} {u[2]:<50} {u[3]}')
"

